const rows = $input.all();
const emails = $('Gmail Trigger Faturas').all();

function norm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

const SOURCES = [];
for (const r of rows) {
  const j = r.json || {};
  if (j.enabled === false) continue;
  if (!j.sender_match) continue;
  SOURCES.push({
    issuer: j.issuer || 'desconhecido',
    senderMatch: norm(j.sender_match),
    subjectMatch: norm(j.subject_match),
    password: j.password == null ? '' : String(j.password)
  });
}

function resolveSource(from, subject) {
  const f = norm(from);
  const s = norm(subject);
  for (const src of SOURCES) {
    if (f.indexOf(src.senderMatch) === -1) continue;
    if (src.subjectMatch && s.indexOf(src.subjectMatch) === -1) continue;
    return src;
  }
  return null;
}

const results = [];
const seen = new Set();
let ignorados = 0;

for (const item of emails) {
  if (!item.binary) continue;
  const j = item.json || {};
  const msgId = j.id || j.threadId || Math.random().toString(36);

  let from = '';
  if (j.from && j.from.value && j.from.value[0]) from = j.from.value[0].address || '';
  if (!from && typeof j.from === 'string') from = j.from;
  if (!from && j.headers && j.headers.from) from = j.headers.from;

  let subject = j.subject || '';
  if (!subject && j.headers && j.headers.subject) subject = j.headers.subject;

  const src = resolveSource(from, subject);
  if (!src) { ignorados++; continue; }

  const rawDate = j.internalDate || j.date || null;
  let emailDate = new Date().toISOString().slice(0, 10);
  if (rawDate) {
    const d = new Date(Number(rawDate) > 0 ? Number(rawDate) : rawDate);
    if (!isNaN(d.getTime())) emailDate = d.toISOString().slice(0, 10);
  }

  for (const key of Object.keys(item.binary)) {
    const bin = item.binary[key];
    const fileName = (bin.fileName || '').trim();
    if (!fileName) continue;
    const isPdf = (bin.mimeType || '').toLowerCase().includes('pdf') || fileName.toLowerCase().endsWith('.pdf');
    if (!isPdf) continue;
    const dedupKey = msgId + '::' + fileName;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    results.push({
      json: { msgId, emailDate, fileName, from, subject, issuer: src.issuer, password: src.password },
      binary: { data: bin }
    });
  }
}

console.log('backfill: ' + results.length + ' pdf(s), ' + ignorados + ' ignorado(s)');
return results;

const src = $('Config e Filtrar PDFs').all();
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const meta = src[i] ? src[i].json : {};
  const pages = (j.pages || []).map(p => 'data:image/png;base64,' + ((p && p.image && p.image.data) || ''));
  let convertError = undefined;
  if (!pages.length) {
    convertError = (j.error && j.error.code) ? (j.error.code + ': ' + j.error.message) : 'sem paginas';
  }
  out.push({ json: Object.assign({}, meta, { pages: pages, pageCount: pages.length, convertError: convertError }) });
}
return out;

const items = $input.all();
const results = [];

const SCHEMA_TEXT = [
  'Voce e um extrator preciso de faturas/extratos de cartao de credito de QUALQUER banco (Portugal ou Brasil).',
  'Voce recebe as PAGINAS da fatura como imagens, em ordem. Devolva EXCLUSIVAMENTE um objeto JSON valido, sem markdown, sem comentarios.',
  '',
  'Schema:',
  '{',
  '  "schema": "card_statement_v1",',
  '  "issuer": string|null,',
  '  "currency": string|null,',
  '  "card_holder": string|null,',
  '  "card_last4": string|null,',
  '  "statement_period": { "open_date": "YYYY-MM-DD"|null, "close_date": "YYYY-MM-DD"|null },',
  '  "due_date": "YYYY-MM-DD"|null,',
  '  "payment_reference": string|null,',
  '  "total_balance": number|null,',
  '  "minimum_payment": number|null,',
  '  "previous_balance": number|null,',
  '  "credits_payments": number|null,',
  '  "credit_limit": number|null,',
  '  "available_limit": number|null,',
  '  "transactions": [',
  '    {',
  '      "date": "YYYY-MM-DD"|null,',
  '      "description": string,',
  '      "merchant": string|null,',
  '      "category": string,',
  '      "amount": number,',
  '      "installment_info": string|null,',
  '      "foreign_amount": number|null,',
  '      "foreign_currency": string|null',
  '    }',
  '  ],',
  '  "warnings": [string]',
  '}',
  '',
  'Regras:',
  '- issuer: nome do banco/emissor como aparece no documento.',
  '- currency: codigo ISO 4217 detectado no documento (BRL, EUR, USD...).',
  '- category e UMA de: mercado, restaurante, transporte, assinaturas, saude, educacao, casa, viagem, tecnologia, lazer, vestuario, servicos_bancarios, taxas, saque, pagamento, outros.',
  '- Numeros com ponto decimal, sem simbolos. "R$ 1.234,56" -> 1234.56 ; "$1,234.56" -> 1234.56',
  '- payment_reference: referencia Multibanco, codigo de barras, boleto ou IBAN, se existir.',
  '- Datas YYYY-MM-DD; se o ano nao estiver explicito, use o ano do periodo da fatura.',
  '- NAO invente valores; ilegivel => null + warnings.',
  '- Cada linha de transacao = um objeto; "Parcela X/Y" vai em installment_info.',
  '- POSITIVO compras, NEGATIVO estornos/pagamentos/creditos.',
  '- Ignore rodapes de marketing, SAC, Ouvidoria, avisos legais.',
  '- Responda SOMENTE o JSON.'
].join('\n');

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const pages = item.json.pages || [];
  if (!pages.length) {
    results.push({ json: Object.assign({}, item.json, { skipped: true }), pairedItem: { item: i } });
    continue;
  }
  const content = [];
  for (const p of pages) content.push({ type: 'image_url', image_url: { url: p } });
  let hint = SCHEMA_TEXT;
  if (item.json.issuer && item.json.issuer !== 'desconhecido') {
    hint = hint + '\n- Dica: este documento deve ser do emissor "' + item.json.issuer + '".';
  }
  content.push({ type: 'text', text: hint });
  const reqBody = { model: 'qwen-plan/qwen3.8-flash', messages: [{ role: 'user', content }], temperature: 0, max_tokens: 12000 };
  const buf = Buffer.from(JSON.stringify(reqBody), 'utf8');
  const bin = await this.helpers.prepareBinaryData(buf, 'llm_body.json', 'application/json');
  results.push({ json: Object.assign({}, item.json, { skipped: false }), binary: { reqbody: bin }, pairedItem: { item: i } });
}
return results;

const llmItems = $input.all();
const src = $('Config e Filtrar PDFs').all();
const results = [];

function parseNum(s) {
  if (s === null || s === undefined) return null;
  if (typeof s === 'number') return isNaN(s) ? null : s;
  let str = String(s).trim().replace(/[^0-9.,-]/g, '');
  if (!str) return null;
  const lastComma = str.lastIndexOf(',');
  const lastDot = str.lastIndexOf('.');
  if (lastComma > -1 && lastDot > -1) {
    if (lastComma > lastDot) str = str.replace(/\./g, '').replace(',', '.');
    else str = str.replace(/,/g, '');
  } else if (lastComma > -1) {
    const decimals = str.length - lastComma - 1;
    if (decimals === 3) str = str.replace(/,/g, '');
    else str = str.replace(',', '.');
  }
  const n = parseFloat(str);
  return isNaN(n) ? null : n;
}

const CATS = ['mercado','restaurante','transporte','assinaturas','saude','educacao','casa','viagem','tecnologia','lazer','vestuario','servicos_bancarios','taxas','saque','pagamento','outros'];
const ISO = /^\d{4}-\d{2}-\d{2}$/;

function slug(s) {
  return String(s || 'banco').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^A-Za-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 24) || 'banco';
}

for (let i = 0; i < llmItems.length; i++) {
  const meta = src[i] ? src[i].json : {};
  const body = llmItems[i].json || {};
  const raw = (body.choices && body.choices[0] && body.choices[0].message ? body.choices[0].message.content : '') || '';

  let data = null, parsedOk = false, error = null;
  try {
    let js = raw;
    const cb = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (cb) js = cb[1];
    const s = js.indexOf('{');
    const e = js.lastIndexOf('}');
    if (s >= 0 && e > s) js = js.slice(s, e + 1);
    data = JSON.parse(js);
    parsedOk = true;
  } catch (err) { error = err.message; }

  if (!data) data = { schema: 'card_statement_v1', transactions: [], warnings: ['parse falhou: ' + error] };
  data.schema = 'card_statement_v1';
  if (!Array.isArray(data.warnings)) data.warnings = [];
  if (!data.issuer && meta.issuer) data.issuer = meta.issuer;

  const txs = Array.isArray(data.transactions) ? data.transactions : [];
  txs.forEach(t => {
    t.amount = parseNum(t.amount);
    t.foreign_amount = parseNum(t.foreign_amount);
    if (!t.category || CATS.indexOf(t.category) === -1) t.category = 'outros';
    if (!(typeof t.date === 'string' && ISO.test(t.date))) t.date = null;
  });
  data.transactions = txs;

  ['total_balance','minimum_payment','previous_balance','credits_payments','credit_limit','available_limit'].forEach(k => { data[k] = parseNum(data[k]); });
  if (data.statement_period) {
    if (data.statement_period.open_date && !ISO.test(data.statement_period.open_date)) data.statement_period.open_date = null;
    if (data.statement_period.close_date && !ISO.test(data.statement_period.close_date)) data.statement_period.close_date = null;
  }
  if (data.due_date && !ISO.test(data.due_date)) data.due_date = null;

  const issuerSlug = slug(meta.issuer || data.issuer);
  const period = (data.statement_period && data.statement_period.close_date) ? data.statement_period.close_date : meta.emailDate;
  const last4 = String(data.card_last4 || '0000').replace(/\D/g, '').slice(-4).padStart(4, '0');
  const uploadName = issuerSlug + '_' + period + '_' + last4 + '_' + String(meta.msgId || '').slice(-8) + '.json';

  results.push({ json: {
    parsedOk, error, uploadName,
    emailDate: meta.emailDate, fonte: meta.issuer, ficheiro: meta.fileName,
    record: data
  }});
}
return results;

const checks = $input.all();
const consolidados = $('Consolidar JSON').all();
const results = [];
let skipped = 0;
for (let i = 0; i < checks.length; i++) {
  const existe = checks[i].json && checks[i].json.files && checks[i].json.files.length > 0;
  if (existe) { skipped++; continue; }
  const orig = consolidados[i];
  if (!orig) continue;
  results.push({ json: orig.json });
}
console.log('dedup: novos=' + results.length + ' duplicados=' + skipped);
return results;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const jsonStr = JSON.stringify(item.json.record, null, 2);
  const buf = Buffer.from(jsonStr, 'utf8');
  const binaryData = await this.helpers.prepareBinaryData(buf, item.json.uploadName, 'application/json');
  results.push({
    json: { uploadName: item.json.uploadName, fonte: item.json.fonte, emailDate: item.json.emailDate },
    binary: { data: binaryData }
  });
}
return results;

const gravados = $input.all();
const nomes = [];
for (const g of gravados) {
  nomes.push((g.json && g.json.name) ? g.json.name : '?');
}
return [{ json: { gravados: gravados.length, ficheiros: nomes } }];
